mapper.sql:
------ selectBlockDetails_withPickupCount {{
select block_detail_seq, chain_id, property_id, block_id, room_type_code, block_date, original_block_room_count , cut_off_block_room_count, shoulder_yn, addon_room_rate, one_person_room_rate, two_person_room_rate, three_person_room_rate , four_person_room_rate, contract_block_room_count, one_person_room_count, two_person_room_count, three_person_room_count , four_person_room_count, block_cut_off_date, create_user_id, create_datetimetz, update_user_id, update_datetimetz , coalesce(BKDD._pickup_count, 0) as pickup_block_room_count , greatest(BKDD._pickup_count, current_block_room_count) as current_block_room_count from hpms.hpbk_block_detail HBLD left join lateral ( select sum(room_count) as _pickup_count from (
) BKDD where BKDD.chain_id = HBLD.chain_id and BKDD.property_id = HBLD.property_id and BKDD.block_id = HBLD.block_id and BKDD.room_booking_date = HBLD.block_date and BKDD.room_type_code = HBLD.room_type_code group by BKDD.chain_id, BKDD.property_id, BKDD.room_booking_date, BKDD.block_id, BKDD.room_type_code ) BKDD on true ------ }} selectBlockDetails_withPickupCount

select coalesce(setting_value, 'N') = 'Y'  as _is_occ_day_use
from fwcm.fwcm_property_setting FPS
where FPS.property_setting_code = 'HPBK_DAY_USE_IS_COUNTED_IN_OCC_YN'
    and FPS.chain_id    = #{chainId}
    and FPS.property_id = #{propertyId}

------ selectBookingDetailStatistics_daily {{ select HBDD.chain_id, HBDD.property_id, HBDD.room_booking_date, HBDD.room_type_code , sum(room_count) filter (where _deduct_yn = 'Y') as deduct , sum(room_count) filter (where _deduct_yn = 'N') as non_deduct
, sum(room_count) filter (where _deduct_yn = 'Y' and _due_in_yn = 'Y') as arrival , sum(room_count) filter (where _deduct_yn = 'Y' and _due_out_yn = 'Y') as departure , sum(room_count) filter (where _deduct_yn = 'Y' and _day_use_yn = 'Y') as day_use , sum(_person_count) filter (where _deduct_yn = 'Y' and _due_in_yn = 'Y') as arrival_person , sum(_person_count) filter (where _deduct_yn = 'Y' and _due_out_yn = 'Y') as departure_person , sum(_person_count) filter (where _deduct_yn = 'Y' and _day_use_yn = 'Y') as day_use_person , sum(adult_count) filter (where _deduct_yn = 'Y' and _in_house_yn = 'Y') as adult_in_house , sum(child_count) filter (where _deduct_yn = 'Y' and _in_house_yn = 'Y') as child_in_house
from (
) HBDD, _statistic_options _opt where HBDD.chain_id = _opt.chainId and HBDD.property_id = _opt.propertyId group by HBDD.chain_id, HBDD.property_id, HBDD.room_booking_date, HBDD.room_type_code ------ }} selectBookingDetailStatistics_daily

------ selectBlockStatistics_daily {{ select HBLD.chain_id, HBLD.property_id, HBLD.block_date, HBLD.room_type_code , sum(current_block_room_count) filter (where _deduct_yn = 'Y') as deduct , sum(pickup_block_room_count) filter (where _deduct_yn = 'Y') as deduct_pickup , sum(current_block_room_count) filter (where _deduct_yn = 'N') as non_deduct , sum(pickup_block_room_count) filter (where _deduct_yn = 'N') as non_deduct_pickup from (
) HBLD join (
) HBLB on HBLB.chain_id = HBLD.chain_id and HBLB.property_id = HBLD.property_id and HBLB.block_id = HBLD.block_id cross join _statistic_options _opt where HBLD.chain_id = _opt.chainId and HBLD.property_id = _opt.propertyId and HBLD.block_date between (_opt.startDate) and (_opt.endDate) group by HBLD.chain_id, HBLD.property_id, HBLD.block_date, HBLD.room_type_code ------ }} selectBlockStatistics_daily

------ selectInventoryRoomStatistics_daily {{ with calendar as ( select generate_series(startDate, endDate, '1 day'::interval)::DATE as date from _statistic_options ) , RTC as (
) , HRO as (
) select RTC.chain_id, RTC.property_id, calendar.date, RTC.room_class_code, RTC.room_type_code, RTC.display_seq, RTC._room_count , count(case when HRO.ooo_status_cd = 'OUT OF ORDER' then true end) as ooo , count(case when HRO.ooo_status_cd = 'OUT OF SERVICE' then true end) as oos from calendar cross join RTC cross join _statistic_options _opt left join HRO on HRO.chain_id = RTC.chain_id and HRO.property_id = RTC.property_id and HRO.room_type_code = RTC.room_type_code and calendar.date between HRO.ooo_start_date and HRO.ooo_end_date where RTC.chain_id = _opt.chainId and RTC.property_id = _opt.propertyId group by RTC.chain_id, RTC.property_id, calendar.date, RTC.room_class_code, RTC.room_type_code, RTC.display_seq, RTC._room_count ------ }} selectInventoryRoomStatistics_daily
